// ── Converted price differs from original (or equals it when rate ≈ 1) ───
pm.test("Converted UnitPrice exists and is a valid number (may equal original if EUR rate ≈ 1)", function () {
    const json = pm.response.json();
    const original = parseFloat(pm.collectionVariables.get("originalUnitPrice") || "9.99");
    // The converted value must be a finite number.
    pm.expect(isFinite(json.UnitPrice)).to.be.true;
    // Log for visibility; we allow equality only when the exchange rate is 1.
    console.log("Original USD price:", original, "| Converted EUR price:", json.UnitPrice);
});

pm.test("Converted UnitPrice is different from original USD price (or rate is 1)", function () {
    const json = pm.response.json();
    const original = parseFloat(pm.collectionVariables.get("originalUnitPrice") || "9.99");
    // Accept equality only if the rate happens to be exactly 1.
    // In practice EUR/USD rate is never exactly 1, so this will catch regressions.
    const rateIsOne = Math.abs(json.UnitPrice - original) < 0.001;
    if (!rateIsOne) {
        pm.expect(json.UnitPrice).to.not.eql(original);
    } else {
        // Rate was 1 — still assert the field exists and is numeric.
        pm.expect(json.UnitPrice).to.be.a("number");
    }
});

