pm.test("Product deleted successfully message returned", function () {
    const json = pm.response.json();
    pm.expect(json.message).to.eql("Product deleted successfully");
});

// ── Save the ID before clearing so the verification step can use it ────────
const pid = pm.collectionVariables.get("productId");
pm.collectionVariables.set("deletedProductId", pid);
// Clear productId so a fresh one is generated on the next run.
pm.collectionVariables.set("productId", "");

// Capture the productId before it was cleared by the DELETE step.
// The DELETE request clears productId; we stored a copy in deletedProductId
// at the end of the DELETE afterResponse script — but as a safety net we
// also read it here from the collection variable set below.
const pid = pm.collectionVariables.get("deletedProductId");
if (!pid || pid === "") {
    // Fallback: if deletedProductId was never set, skip gracefully.
    console.warn("deletedProductId not set — skipping deletion-verification request.");
}

// ── Status code ──────────────────────────────────────────────────────────
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// ── Response time ─────────────────────────────────────────────────────────
pm.test("Response time is under 3000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

// ── Product should no longer exist ────────────────────────────────────────
pm.test("Deleted product is no longer retrievable (returns 'not found' message)", function () {
    const json = pm.response.json();
    pm.expect(json).to.be.an("object");
    pm.expect(json).to.have.property("message");
    pm.expect(json.message).to.eql("Product not found");
});

// ── Clean up the deletedProductId variable ────────────────────────────────
pm.collectionVariables.set("deletedProductId", "");

// Generate a unique ProductID once per collection run and store it.
// Subsequent requests read it from the collection variable.
if (!pm.collectionVariables.get("productId") || pm.collectionVariables.get("productId") === "") {
    const randomSuffix = Math.random().toString(36).substring(2, 8).toUpperCase();
    const productId = "TEST-" + randomSuffix;
    pm.collectionVariables.set("productId", productId);
    console.log("Generated ProductID:", productId);
}

